@Service
public class WalletService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public WalletService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new WalletEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(WalletRepository.class) );
		this.validator		= applicationContext.getBean(WalletValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Wallet
	 */
		public Wallet createWallet( CreateWalletCommand command ) {

		Wallet entity = new Wallet();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWalletId( command.getWalletId() );
            entity.setCurrency( command.getCurrency() );
            entity.setBalance( command.getBalance() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Wallet {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateWalletCommand
	 * @return		Wallet
	 */
	public Wallet updateWallet( UpdateWalletCommand command ) {

		Wallet entity = new Wallet();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWalletId( command.getWalletId() );
            entity.setCurrency( command.getCurrency() );
            entity.setBalance( command.getBalance() );
            entity.setCustomer( command.getCustomer() );
            entity.setTransactions( command.getTransactions() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Wallet {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteWalletCommand
	 */
	public void delete( DeleteWalletCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getWalletId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Wallet {0} ", id );

	}

	/**
	 * Method to retrieve the Wallet via WalletFetchOneSummary
	 * @param 	summary WalletFetchOneSummary
	 * @return 	WalletFetchOneResponse
	 */
	public Wallet getWallet( WalletFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "WalletFetchOneSummary arg cannot be null" );

		Wallet entity = null;
		UUID id = summary.getWalletId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Wallet using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Wallets
	 *
	 * @return 	List<Wallet>
	 */
    public List<Wallet> getAllWallet() {
		List<Wallet> list = projector.findAll( new FindAllWalletQuery() );
		return list;
	}

	/**
	 * assign Customer on Wallet
	 * @param		command AssignCustomerToWalletCommand
	 */
	public void assignCustomer( AssignCustomerToWalletCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getWalletId(), command.getAssignment());

	}

	/**
	 * unAssign Customer on Wallet
	 * @param		command UnAssignCustomerFromWalletCommand
	 */
	public void unAssignCustomer( UnAssignCustomerFromWalletCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignCustomer(command.getWalletId());
	}
	

	/**
	 * add Transaction to Transactions
	 * @param		command AssignTransactionsToWalletCommand
	 */
	public void addToTransactions( AssignTransactionsToWalletCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToTransactions(command.getWalletId(), command.getAddTo());
	}

	/**
	 * remove Transaction from Transactions
	 * @param		command RemoveTransactionsFromWalletCommand
	 */
	public void removeFromTransactions( RemoveTransactionsFromWalletCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromTransactions(command.getWalletId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final WalletEntityProjector projector;
	private final WalletValidator validator;
	private Wallet wallet 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(WalletService.class);
}
